-- Province level (ES/IT provinces, FR departments, PT districts): breadcrumbs, landing pages,
-- search scope; plus "nearby areas" links that only point to places with listings.

create table public.provinces (
  id bigint generated always as identity primary key,
  country_code char(2) not null references public.countries (code),
  code text not null unique,
  name text not null,
  slug text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  unique (country_code, slug)
);
alter table public.provinces enable row level security;
create policy "provinces are public" on public.provinces for select to anon, authenticated using (true);
grant select on public.provinces to anon, authenticated;

alter table public.cities add column province_id bigint references public.provinces (id);
create index cities_province_idx on public.cities (province_id);

