-- Search functions gain a province scope (new signature, so the old ones are dropped first).
drop function public.search_listings(public.listing_operation, char, bigint, bigint, public.property_type[], integer, integer,
  integer, integer, integer, integer, text[], double precision, double precision, double precision, double precision, text, integer, integer);
drop function public.search_listing_markers(public.listing_operation, char, bigint, bigint, public.property_type[], integer, integer,
  integer, integer, integer, integer, text[], double precision, double precision, double precision, double precision);

create or replace function public.search_listings(
  p_operation public.listing_operation,
  p_country char(2) default null,
  p_city_id bigint default null,
  p_province_id bigint default null,
  p_neighborhood_id bigint default null,
  p_types public.property_type[] default null,
  p_price_min integer default null,
  p_price_max integer default null,
  p_bedrooms_min integer default null,
  p_bathrooms_min integer default null,
  p_area_min integer default null,
  p_area_max integer default null,
  p_features text[] default null,
  p_west double precision default null,
  p_south double precision default null,
  p_east double precision default null,
  p_north double precision default null,
  p_sort text default 'newest',
  p_limit integer default 24,
  p_offset integer default 0
)
returns jsonb
language sql
stable
set search_path = ''
as $$
  with filtered as (
    select l.*
    from public.listings l
    where l.status = 'active'
      and l.operation = p_operation
      and (p_country is null or l.country_code = p_country)
      and (p_city_id is null or l.city_id = p_city_id)
      and (p_province_id is null or l.city_id in (select id from public.cities where province_id = p_province_id))
      and (p_neighborhood_id is null or l.neighborhood_id = p_neighborhood_id)
      and (p_types is null or l.property_type = any (p_types))
      and (p_price_min is null or l.price >= p_price_min)
      and (p_price_max is null or l.price <= p_price_max)
      and (p_bedrooms_min is null or l.bedrooms >= p_bedrooms_min)
      and (p_bathrooms_min is null or l.bathrooms >= p_bathrooms_min)
      and (p_area_min is null or l.area_m2 >= p_area_min)
      and (p_area_max is null or l.area_m2 <= p_area_max)
      and (p_features is null or l.features @> p_features)
      and (p_west is null or l.location operator(extensions.&&)
           extensions.st_makeenvelope(p_west, p_south, p_east, p_north, 4326)::extensions.geography)
  ),
  page as (
    select f.*, count(*) over () as total_count
    from filtered f
    order by
      case when p_sort = 'price_asc' then f.price end asc,
      case when p_sort = 'price_desc' then f.price end desc,
      case when p_sort = 'area_desc' then f.area_m2 end desc,
      case when p_sort = 'price_m2_asc' then f.price::numeric / nullif(f.area_m2, 0) end asc,
      f.published_at desc, f.id desc
    limit least(greatest(p_limit, 1), 60)
    offset greatest(p_offset, 0)
  )
  select jsonb_build_object(
    'total', coalesce((select total_count from page limit 1), (select count(*) from filtered)),
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id,
      'title', p.title,
      'excerpt', left(regexp_replace(coalesce(p.description, ''), '\s+', ' ', 'g'), 260),
      'operation', p.operation,
      'property_type', p.property_type,
      'price', p.price,
      'previous_price', p.previous_price,
      'area_m2', p.area_m2,
      'bedrooms', p.bedrooms,
      'bathrooms', p.bathrooms,
      'floor', p.floor,
      'exterior', p.exterior,
      'features', p.features,
      'published_at', p.published_at,
      'city', c.name,
      'city_slug', c.slug,
      'country_code', p.country_code,
      'neighborhood', n.name,
      'seller_type', coalesce(pp.seller_type, 'private'),
      'has_phone', public.listing_has_phone(p.id),
      'lat', extensions.st_y(p.location::extensions.geometry),
      'lng', extensions.st_x(p.location::extensions.geometry),
      'photo_count', (select count(*) from public.listing_photos where listing_id = p.id),
      'photos', (select coalesce(jsonb_agg(ph.storage_path order by ph.position, ph.created_at), '[]'::jsonb)
                   from (select * from public.listing_photos where listing_id = p.id
                         order by position, created_at limit 20) ph)
    ) order by
      case when p_sort = 'price_asc' then p.price end asc,
      case when p_sort = 'price_desc' then p.price end desc,
      case when p_sort = 'area_desc' then p.area_m2 end desc,
      case when p_sort = 'price_m2_asc' then p.price::numeric / nullif(p.area_m2, 0) end asc,
      p.published_at desc, p.id desc), '[]'::jsonb)
  )
  from page p
  join public.cities c on c.id = p.city_id
  left join public.neighborhoods n on n.id = p.neighborhood_id
  left join public.public_profiles pp on pp.id = p.owner_id;
$$;
grant execute on function public.search_listings to anon, authenticated;

create or replace function public.search_listing_markers(
  p_operation public.listing_operation,
  p_country char(2) default null,
  p_city_id bigint default null,
  p_province_id bigint default null,
  p_neighborhood_id bigint default null,
  p_types public.property_type[] default null,
  p_price_min integer default null,
  p_price_max integer default null,
  p_bedrooms_min integer default null,
  p_bathrooms_min integer default null,
  p_area_min integer default null,
  p_area_max integer default null,
  p_features text[] default null,
  p_west double precision default null,
  p_south double precision default null,
  p_east double precision default null,
  p_north double precision default null
)
returns table (id bigint, price integer, lat double precision, lng double precision)
language sql
stable
set search_path = ''
as $$
  select l.id, l.price, extensions.st_y(l.location::extensions.geometry), extensions.st_x(l.location::extensions.geometry)
  from public.listings l
  where l.status = 'active'
    and l.operation = p_operation
    and (p_country is null or l.country_code = p_country)
    and (p_city_id is null or l.city_id = p_city_id)
    and (p_province_id is null or l.city_id in (select id from public.cities where province_id = p_province_id))
    and (p_neighborhood_id is null or l.neighborhood_id = p_neighborhood_id)
    and (p_types is null or l.property_type = any (p_types))
    and (p_price_min is null or l.price >= p_price_min)
    and (p_price_max is null or l.price <= p_price_max)
    and (p_bedrooms_min is null or l.bedrooms >= p_bedrooms_min)
    and (p_bathrooms_min is null or l.bathrooms >= p_bathrooms_min)
    and (p_area_min is null or l.area_m2 >= p_area_min)
    and (p_area_max is null or l.area_m2 <= p_area_max)
    and (p_features is null or l.features @> p_features)
    and (p_west is null or l.location operator(extensions.&&)
         extensions.st_makeenvelope(p_west, p_south, p_east, p_north, 4326)::extensions.geography)
  order by l.published_at desc
  limit 500;
$$;
grant execute on function public.search_listing_markers to anon, authenticated;

-- Up to p_limit places around the current scope that have active listings for this search:
-- other neighbourhoods of the city first (closest first), then the closest cities.
create or replace function public.nearby_places(
  p_operation public.listing_operation,
  p_types public.property_type[] default null,
  p_country char(2) default null,
  p_province_id bigint default null,
  p_city_id bigint default null,
  p_neighborhood_id bigint default null,
  p_limit integer default 6
)
returns table (kind text, name text, slug text, city_slug text, listings bigint)
language sql
stable
set search_path = ''
as $$
  with active as (
    select l.city_id, l.neighborhood_id
    from public.listings l
    where l.status = 'active' and l.operation = p_operation
      and (p_types is null or l.property_type = any (p_types))
      and (p_country is null or l.country_code = p_country)
  ),
  city_counts as (select city_id, count(*) as n from active group by city_id),
  hood_counts as (select neighborhood_id, count(*) as n from active where neighborhood_id is not null group by neighborhood_id),
  here as (
    select coalesce(
      (select location from public.neighborhoods where id = p_neighborhood_id),
      (select location from public.cities where id = p_city_id)
    ) as location
  ),
  hoods as (
    select 'neighborhood'::text as kind, nb.name, nb.slug, c.slug as city_slug, k.n as listings,
           extensions.st_distance(nb.location, (select location from here)) as dist
    from hood_counts k
    join public.neighborhoods nb on nb.id = k.neighborhood_id
    join public.cities c on c.id = nb.city_id
    where p_neighborhood_id is not null and nb.city_id = p_city_id and nb.id <> p_neighborhood_id
  ),
  places as (
    select 'city'::text as kind, c.name, c.slug, c.slug as city_slug, k.n as listings,
           case when (select location from here) is null then null
                else extensions.st_distance(c.location, (select location from here)) end as dist
    from city_counts k
    join public.cities c on c.id = k.city_id
    where (p_city_id is null or c.id <> p_city_id)
      and (p_province_id is null or c.province_id = p_province_id)
  )
  select kind, name, slug, city_slug, listings
  from (
    select *, 0 as rank_group from hoods
    union all
    select *, 1 as rank_group from places
  ) all_places
  order by rank_group, dist nulls last, listings desc, name
  limit least(greatest(p_limit, 1), 12);
$$;
grant execute on function public.nearby_places to anon, authenticated;

-- Province + city in one call for breadcrumbs.
create or replace function public.get_province(p_id bigint)
returns table (id bigint, country_code char(2), name text, slug text)
language sql
stable
set search_path = ''
as $$
  select id, country_code, name, slug from public.provinces where id = p_id;
$$;
grant execute on function public.get_province(bigint) to anon, authenticated;
